import csv
import io
import re
from typing import Any, Dict, List

_INT_RE = re.compile(r"^[+-]?\d+$", re.ASCII)
_NUM_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$", re.ASCII)


def _parse_value(value: str) -> Any:
    if value is None or value == "":
        return None

    stripped = value.strip()
    if _NUM_RE.fullmatch(stripped):
        if _INT_RE.fullmatch(stripped):
            return int(stripped)
        return float(stripped)

    return value


def merge_csv_texts(csv_texts: List[str]) -> List[Dict[str, Any]]:
    if not csv_texts:
        return []

    parsed = []
    all_columns: List[str] = []
    seen = set()

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))

        headers: List[str] = []
        for row in reader:
            if row:
                headers = row
                break

        # Strip BOM if present on the first header cell.
        if headers and headers[0].startswith("\ufeff"):
            headers[0] = headers[0][1:]

        rows = [row for row in reader if row]  # skip blank lines
        parsed.append((headers, rows))

        for col in headers:
            if col not in seen:
                seen.add(col)
                all_columns.append(col)

    result: List[Dict[str, Any]] = []

    for headers, rows in parsed:
        for row in rows:
            record = {col: None for col in all_columns}
            for col, value in zip(headers, row):
                record[col] = _parse_value(value)
            result.append(record)

    return result
