from collections import Counter
from math import sqrt

def letter_count_correlations(strings):
    if not strings:
        return None

    # Include only letters that appear at least once
    letters = sorted({ch for s in strings for ch in s})
    if not letters:
        return {}

    counters = [Counter(s) for s in strings]
    n = len(strings)

    # matrix[i][j] = count of letters[j] in strings[i]
    matrix = [[c[ch] for ch in letters] for c in counters]
    columns = list(zip(*matrix))  # one tuple per letter

    means = [sum(col) / n for col in columns]
    centered = [[v - mean for v in col] for col, mean in zip(columns, means)]
    ss = [sum(v * v for v in cent) for cent in centered]  # sum of squared deviations

    result = {}
    for i, x in enumerate(letters):
        result[x] = {}
        for j, y in enumerate(letters):
            if i == j:
                result[x][y] = 1.0
            else:
                numerator = sum(a * b for a, b in zip(centered[i], centered[j]))
                denominator = sqrt(ss[i] * ss[j])
                r = numerator / denominator if denominator else 0.0

                # Clean up tiny floating-point drift for perfect correlations
                if abs(r - 1.0) < 1e-12:
                    r = 1.0
                elif abs(r + 1.0) < 1e-12:
                    r = -1.0

                result[x][y] = r

    return result
