import csv
import io
import math

def normalize_numeric_columns(csv_text):
    def parse_number(value):
        try:
            num = float(value)
        except (TypeError, ValueError):
            return None
        return num if math.isfinite(num) else None

    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        raise ValueError("no numeric columns")

    header = rows[0]
    data = rows[1:]

    columns = {name: [] for name in header}
    for row in data:
        for i, name in enumerate(header):
            columns[name].append(row[i] if i < len(row) else "")

    numeric = {}
    for name in header:
        values = columns[name]
        if not values:
            continue

        nums = []
        for value in values:
            num = parse_number(value)
            if num is None:
                nums = None
                break
            nums.append(num)

        if nums is not None:
            numeric[name] = nums

    if not numeric:
        raise ValueError("no numeric columns")

    result = {}
    for name in header:
        if name in numeric:
            nums = numeric[name]
            lo, hi = min(nums), max(nums)
            if hi == lo:
                result[name] = [0.0] * len(nums)
            else:
                result[name] = [(x - lo) / (hi - lo) for x in nums]
        else:
            result[name] = columns[name]

    return result
```

A column is treated as numeric only if every value in that column can be parsed as a finite float. Non-numeric columns are returned unchanged as strings.

