from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag):
        super().__init__(convert_charrefs=True)  # decodes HTML entities
        self.target = tag.lower()
        self.capturing = False
        self.depth = 0
        self.parts = []
        self.done = False
        self.result = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()

        # Void elements have no text content.
        if tag in _VOID_TAGS:
            if tag == self.target:
                self.done = True
                self.result = None
            return

        if self.capturing:
            if tag == self.target:
                self.depth += 1
        elif tag == self.target:
            self.capturing = True
            self.depth = 1
            self.parts = []

    def handle_startendtag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()

        if tag in _VOID_TAGS:
            if tag == self.target:
                self.done = True
                self.result = None
            return

        # In HTML, a trailing slash on a non-void element is ignored.
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if self.done:
            return
        tag = tag.lower()

        if self.capturing and tag == self.target:
            self.depth -= 1
            if self.depth == 0:
                text = "".join(self.parts)
                self.done = True
                self.result = text if text else None

    def handle_data(self, data):
        if self.capturing and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    """Return text content of the first element with the given tag name."""
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    # If the target element was never closed, use whatever text was captured.
    if parser.capturing and not parser.done:
        text = "".join(parser.parts)
        parser.result = text if text else None

    return parser.result
```

