def remove_zscore_outliers(rows, column, threshold):
    if not rows:
        return [], []

    values = [row[column] for row in rows]
    n = len(values)

    mean = sum(values) / n
    std = (sum((v - mean) ** 2 for v in values) / n) ** 0.5  # population std

    kept = []
    outliers = []

    for i, row in enumerate(rows):
        if std == 0:
            z = 0.0
        else:
            z = (row[column] - mean) / std

        if abs(z) > threshold:
            outliers.append(i)
        else:
            kept.append(row)

    return kept, sorted(outliers)
```

