import math

def standardize_columns(data):
    result = {}

    for col, values in data.items():
        present = [x for x in values if x is not None]

        if not present:
            result[col] = [0.0] * len(values)
            continue

        mean = sum(present) / len(present)
        n = len(values)

        # Missing values are filled with the mean, so their squared deviation is 0.
        variance = sum((x - mean) ** 2 for x in present) / n
        std = math.sqrt(variance)

        if std == 0.0:
            result[col] = [0.0] * n
        else:
            result[col] = [
                0.0 if x is None else (x - mean) / std
                for x in values
            ]

    return result
```

