def min_max_scale_columns(data, columns):
    """
    Return a new dict where the specified columns are min-max scaled to [0, 1].
    Other columns are left unchanged. Constant columns become all zeros.
    """
    to_scale = set(columns)
    result = {}

    for col, values in data.items():
        if col in to_scale:
            if not values:
                result[col] = []
                continue

            low = min(values)
            high = max(values)
            span = high - low

            if span == 0:
                result[col] = [0.0] * len(values)
            else:
                result[col] = [(v - low) / span for v in values]
        else:
            result[col] = list(values)

    return result
```

