import re
from collections import Counter

def keyword_article_word_counts(articles):
    # Validate required keys on every article first
    for article in articles:
        if 'Title' not in article or 'Content' not in article:
            raise ValueError("Each article must have 'Title' and 'Content' keys")

    counts = Counter()

    for article in articles:
        title = article['Title'].lower()

        # Select if title contains 'like' or 'what' anywhere, ignoring case
        if 'like' in title or 'what' in title:
            # Extract alphanumeric words, leaving out punctuation, preserving case
            words = re.findall(r"[A-Za-z0-9]+", article['Content'])
            counts.update(words)

    return dict(counts)
