```python
from html.parser import HTMLParser

_VOID_TAGS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
})

class _Node:
    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []

class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node('#root')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)
        if tag not in _VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        if data:
            self.stack[-1].children.append(data)

def _classes(node):
    return (node.attrs.get('class') or '').split()

def _text(node):
    parts = []

    def walk(n):
        for child in n.children:
            if isinstance(child, _Node):
                walk(child)
            else:
                parts.append(child)

    walk(node)
    return ''.join(parts).strip()

def _find_first(node, predicate):
    for child in node.children:
        if isinstance(child, _Node):
            if predicate(child):
                return child
            found = _find_first(child, predicate)
            if found is not None:
                return found
    return None

def extract_article_info(html):
    parser = _TreeBuilder()
    parser.feed(html)
    parser.close()

    result = []

    def visit(node):
        for child in node.children:
            if not isinstance(child, _Node):
                continue

            if 'container' in _classes(child):
                h1 = _find_first(child, lambda n: n.tag == 'h1')
                date_span = _find_first(
                    child,
                    lambda n: n.tag == 'span' and 'date' in _classes(n)
                )
                author_span = _find_first(
                    child,
                    lambda n: n.tag == 'span' and 'author' in _classes(n)
                )

                title = _text(h1) if h1 is not None else 'No Title'
                date = _text(date_span) if date_span is not None else 'No Date'
                author = _text(author_span) if author_span is not None else 'No Author'

                result.append((title, date, author))

            visit(child)

    visit(parser.root)
    return result
```

Example usage:

```python
extract_article_info('<div class="container"><h1>Hello</h1><span class="author">Ann</span></div>')
# [('Hello', 'No Date', 'Ann')]
```

