import statistics

def merge_and_standardize(rows1, rows2):
    # Collect feature column names from each table, preserving first-seen order.
    cols1 = []
    seen = {'id'}
    for row in rows1:
        for key in row:
            if key != 'id' and key not in seen:
                seen.add(key)
                cols1.append(key)

    cols2 = []
    seen = {'id'}
    for row in rows2:
        for key in row:
            if key != 'id' and key not in seen:
                seen.add(key)
                cols2.append(key)

    # Group rows by id to perform an outer join.
    groups1 = {}
    for row in rows1:
        groups1.setdefault(row['id'], []).append(row)

    groups2 = {}
    for row in rows2:
        groups2.setdefault(row['id'], []).append(row)

    all_ids = sorted(set(groups1) | set(groups2))

    # Compute mean and population std for each first-table feature column,
    # ignoring missing values (None).
    stats = {}
    for col in cols1:
        vals = [row[col] for row in rows1 if col in row and row[col] is not None]
        if vals:
            mean = statistics.mean(vals)
            std = statistics.pstdev(vals)
            # Constant columns should become 0.
            if all(v == vals[0] for v in vals):
                std = 0.0
        else:
            mean = std = None
        stats[col] = (mean, std)

    merged = []
    for i in all_ids:
        rs1 = groups1.get(i, [])
        rs2 = groups2.get(i, [])

        if rs1 and rs2:
            pairs = [(r1, r2) for r1 in rs1 for r2 in rs2]
        elif rs1:
            pairs = [(r1, None) for r1 in rs1]
        else:
            pairs = [(None, r2) for r2 in rs2]

        for r1, r2 in pairs:
            out = {'id': i}

            # Standardized first-table columns.
            for col in cols1:
                if r1 is not None and col in r1 and r1[col] is not None:
                    mean, std = stats[col]
                    if std is None:
                        out[col] = None
                    elif std == 0.0:
                        out[col] = 0.0
                    else:
                        out[col] = (r1[col] - mean) / std
                else:
                    out[col] = None

            # Second-table columns are left unchanged.
            for col in cols2:
                out[col] = r2.get(col) if r2 is not None else None

            merged.append(out)

    return merged
