import math

def standardize_columns(rows):
    """Standardize each column to mean 0 and population standard deviation 1.

    Constant columns become all zeros. Raises ValueError if rows is empty.
    """
    if len(rows) == 0:
        raise ValueError("rows must not be empty")

    n = len(rows)
    ncols = len(rows[0])
    result = [[0.0] * ncols for _ in range(n)]

    for j in range(ncols):
        col = [row[j] for row in rows]
        mean = sum(col) / n

        if min(col) == max(col):
            std = 0.0
        else:
            variance = sum((x - mean) ** 2 for x in col) / n
            std = math.sqrt(variance)

        for i in range(n):
            if std == 0.0:
                result[i][j] = 0.0
            else:
                result[i][j] = (rows[i][j] - mean) / std

    return result
