def scale_table_columns(data):
    if not data:
        return {}

    columns = list(data.keys())
    rows = zip(*(data[col] for col in columns))

    kept_rows = [
        row for row in rows
        if all(value is not None for value in row)
    ]

    if not kept_rows:
        return {col: [] for col in columns}

    result = {}
    for i, col in enumerate(columns):
        values = [row[i] for row in kept_rows]
        low = min(values)
        high = max(values)

        if low == high:
            result[col] = [0.0] * len(values)
        else:
            result[col] = [(v - low) / (high - low) for v in values]

    return result
