import math

def standardize_numeric_columns(data):
    result = {}

    for col, values in data.items():
        # Try to convert every value in the column to float.
        try:
            nums = [float(v) for v in values]
        except (TypeError, ValueError, OverflowError):
            # If any value cannot be converted, leave the column unchanged.
            result[col] = values
            continue

        n = len(nums)

        if n == 0:
            result[col] = []
            continue

        # A constant column becomes all zeros.
        if all(x == nums[0] for x in nums):
            result[col] = [0.0] * n
            continue

        mean = sum(nums) / n
        std = math.sqrt(sum((x - mean) ** 2 for x in nums) / n)

        if std == 0.0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / std for x in nums]

    return result
