import math

def weather_column_summary(column, data):
    column_index = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4
    }[column]

    values = [row[column_index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10
        }

    total = sum(values)
    mean = total / len(values)
    min_val = min(values)
    max_val = max(values)

    histogram = [0] * 10

    if min_val == max_val:
        # All values are equal to the max, so they go into the last bin.
        histogram[9] = len(values)
    else:
        width = (max_val - min_val) / 10

        for value in values:
            if value == max_val:
                histogram[9] += 1
            else:
                bin_index = math.floor((value - min_val) / width + 1e-12)
                if bin_index < 0:
                    bin_index = 0
                elif bin_index > 9:
                    bin_index = 9
                histogram[bin_index] += 1

    return {
        'sum': total,
        'mean': mean,
        'min': min_val,
        'max': max_val,
        'histogram': histogram
    }
