        published_time = article["published_time"]

        # Normalize ISO 8601 'Z' to '+00:00' for older Python compatibility
        if isinstance(published_time, str) and published_time.endswith(("Z", "z")):
            published_time = published_time[:-1] + "+00:00"

        local_hour = datetime.fromisoformat(published_time).astimezone(tz).hour
        hours_by_category[category].append(local_hour)

    return {
        category: {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }
        for category, hours in sorted(hours_by_category.items())
    }
