Here is a self-contained implementation using `Counter` and a deterministic Lloyd’s k-means:

```python
from collections import Counter

def _dist2(a, b):
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def _mean(cluster):
    n = len(cluster)
    return (
        sum(p[0] for p in cluster) / n,
        sum(p[1] for p in cluster) / n
    )

def _initial_centroids(points, k):
    # Deterministic farthest-point initialization
    centroids = [points[0]]
    while len(centroids) < k:
        best_point = None
        best_dist = -1.0
        for p in points:
            d = min(_dist2(p, c) for c in centroids)
            if d > best_dist:
                best_dist = d
                best_point = p
        centroids.append(best_point)
    return centroids

def _kmeans(points, k):
    k = min(k, len(points))
    if k <= 0:
        return []

    centroids = _initial_centroids(points, k)

    for _ in range(100):
        clusters = [[] for _ in range(k)]

        for p in points:
            idx = min(range(k), key=lambda i: _dist2(p, centroids[i]))
            clusters[idx].append(p)

        # Repair any empty cluster by moving a point from a larger cluster
        for i in range(k):
            if not clusters[i]:
                chosen = None
                chosen_dist = -1.0
                for j in range(k):
                    if j != i and len(clusters[j]) > 1:
                        for p in clusters[j]:
                            d = _dist2(p, centroids[j])
                            if d > chosen_dist:
                                chosen_dist = d
                                chosen = (j, p)
                if chosen is not None:
                    j, p = chosen
                    clusters[j].remove(p)
                    clusters[i].append(p)

        new_centroids = [
            _mean(c) if c else centroids[i]
            for i, c in enumerate(clusters)
        ]

        if all(_dist2(centroids[i], new_centroids[i]) < 1e-12 for i in range(k)):
            centroids = new_centroids
            break
        centroids = new_centroids

    # Final assignment with converged centroids
    clusters = [[] for _ in range(k)]
    for p in points:
        idx = min(range(k), key=lambda i: _dist2(p, centroids[i]))
        clusters[idx].append(p)

    return [c for c in clusters if c]


def cluster_unique_points(points, n_clusters):
    pts = [tuple(p) for p in points]
    counts = Counter(pts)

    distinct = sorted(counts)
    duplicates = {p: counts[p] for p in distinct if counts[p] > 1}

    k = int(min(n_clusters, len(distinct)))
    clusters = _kmeans(distinct, k) if k > 0 else []

    clusters = [sorted(cluster) for cluster in clusters]
    clusters.sort()

    return duplicates, clusters
```

