import math

def column_correlations(data):
    """
    Return the pairwise Pearson correlation matrix of the columns in `data`
    as a nested dict: result[x][y].
    """
    cols = list(data.keys())
    if not cols:
        return {}

    n = len(data[cols[0]])
    if n == 0:
        return {x: {y: float('nan') for y in cols} for x in cols}

    means = {c: sum(vals) / n for c, vals in data.items()}
    centered = {c: [v - means[c] for v in data[c]] for c in cols}
    variances = {c: sum(v * v for v in centered[c]) for c in cols}

    result = {}
    for x in cols:
        result[x] = {}
        for y in cols:
            denom = math.sqrt(variances[x] * variances[y])
            if denom == 0:
                # Pearson is undefined for a constant column paired with
                # another column; a column with itself is conventionally 1.0.
                result[x][y] = 1.0 if x == y else float('nan')
            else:
                cov = sum(a * b for a, b in zip(centered[x], centered[y]))
                result[x][y] = cov / denom

    return result
