import math
import cmath

def spectrum_magnitude_histogram(pairs):
    if not pairs:
        return ([], [])

    values = [v for _, v in pairs]
    n = len(values)

    # Standard unnormalized DFT, coefficients in order k = 0..n-1
    magnitudes = []
    for k in range(n):
        coeff = 0j
        for t, x in enumerate(values):
            coeff += x * cmath.exp(-2j * math.pi * k * t / n)
        magnitudes.append(abs(coeff))

    lo = min(magnitudes)
    hi = max(magnitudes)
    counts = [0] * 10

    if hi == lo:
        # All magnitudes equal: place them all in the last bin
        counts[9] = len(magnitudes)
    else:
        width = (hi - lo) / 10.0
        for m in magnitudes:
            idx = int((m - lo) / width)
            if idx >= 10:   # last bin includes the right edge
                idx = 9
            elif idx < 0:
                idx = 0
            counts[idx] += 1

    return (magnitudes, counts)
