def standardize_by_group(records):
    records = list(records)
    required = ("id", "age", "income")

    for rec in records:
        missing = [key for key in required if key not in rec]
        if missing:
            raise ValueError(f"Record is missing required key(s): {missing}")

    groups = {}
    for idx, rec in enumerate(records):
        groups.setdefault(rec["id"], []).append(idx)

    result = [dict(rec) for rec in records]  # preserves order and any extra keys

    for indices in groups.values():
        for field in ("age", "income"):
            values = [records[i][field] for i in indices]

            # Constant within the group -> z-score is 0
            if min(values) == max(values):
                for i in indices:
                    result[i][field] = 0.0
                continue

            n = len(values)
            mean = sum(values) / n
            variance = sum((v - mean) ** 2 for v in values) / n
            std = variance ** 0.5

            for i in indices:
                result[i][field] = float((records[i][field] - mean) / std)

    return result
