        # Constant column -> all zeros
        if all(v == values[0] for v in values):
            for row in result:
                row[idx] = 0.0
            continue

        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n  # population variance
        std = math.sqrt(variance)

        if std == 0.0:
            for row in result:
                row[idx] = 0.0
        else:
            for i in range(n):
                result[i][idx] = (values[i] - mean) / std

    return result
