        raise ValueError("input contains no numbers")

    def quantile(q):
        # Linear interpolation method: position = (n - 1) * q
        pos = (len(data) - 1) * q
        lo = math.floor(pos)
        hi = math.ceil(pos)

        if lo == hi:
            return float(data[lo])

        frac = pos - lo
        return float(data[lo] * (1.0 - frac) + data[hi] * frac)

    q1 = quantile(0.25)
    q3 = quantile(0.75)

    return float(q3 - q1)
```

