from math import floor

def quartiles_of_string_groups(groups):
    values = sorted(int(s) for group in groups for s in group)

    if not values:
        raise ValueError("at least one value is required")

    n = len(values)

    def percentile(p):
        pos = p * (n - 1)          # 0-based linear interpolation index
        lo = floor(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return float(values[lo] + frac * (values[hi] - values[lo]))

    return (percentile(0.25), percentile(0.50), percentile(0.75))
