import math

def standardize_and_correlate(rows):
    if not rows:
        return [], []

    n = len(rows)
    m = len(rows[0])

    # Copy input and impute missing values with the mean of non-missing values
    data = [list(row) for row in rows]

    for j in range(m):
        present = [data[i][j] for i in range(n) if data[i][j] is not None]
        col_mean = sum(present) / len(present) if present else 0.0
        for i in range(n):
            if data[i][j] is None:
                data[i][j] = col_mean

    # Compute column means, population variances, and population standard deviations
    means = []
    variances = []
    stds = []

    for j in range(m):
        col = [data[i][j] for i in range(n)]
        mu = sum(col) / n
        var = sum((x - mu) ** 2 for x in col) / n
        means.append(mu)
        variances.append(var)
        stds.append(math.sqrt(var))

    # Standardize each column to zero mean and unit variance
    standardized = []
    for i in range(n):
        row = []
        for j in range(m):
            if stds[j] > 0:
                row.append((data[i][j] - means[j]) / stds[j])
            else:
                row.append(0.0)
        standardized.append(row)

    # Pearson correlation matrix
    corr = []
    for j in range(m):
        corr_row = []
        for k in range(m):
            if variances[j] > 0 and variances[k] > 0:
                cov = sum(
                    (data[i][j] - means[j]) * (data[i][k] - means[k])
                    for i in range(n)
                ) / n
                r = cov / math.sqrt(variances[j] * variances[k])

                if j == k:
                    r = 1.0
                elif r > 1.0:
                    r = 1.0
                elif r < -1.0:
                    r = -1.0
            else:
                # Pearson correlation is undefined for zero-variance columns
                r = 1.0 if j == k else float('nan')
            corr_row.append(r)
        corr.append(corr_row)

    return standardized, corr
