import re
import math

def tfidf_without_urls(texts):
    tokenized_docs = []
    for text in texts:
        lowered = text.lower()
        without_urls = re.sub(r'https?://\S+', ' ', lowered)
        words = re.findall(r'\w{2,}', without_urls)
        tokenized_docs.append(words)

    n = len(texts)
    if n == 0:
        return [], []

    df = {}
    for words in tokenized_docs:
        for word in set(words):
            df[word] = df.get(word, 0) + 1

    vocab = sorted(df)
    if not vocab:
        return [], []

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in vocab
    }

    rows = []
    for words in tokenized_docs:
        counts = {}
        for word in words:
            counts[word] = counts.get(word, 0) + 1

        row = [counts.get(word, 0) * idf[word] for word in vocab]
        norm = math.sqrt(sum(x * x for x in row))
        if norm > 0:
            row = [x / norm for x in row]
        rows.append(row)

    return rows, vocab
