import re
import math
from collections import Counter, defaultdict

def tfidf_scores_for_question_articles(titles, contents):
    # Pick articles whose titles contain "how" or "what" anywhere, case-insensitive
    picked_bodies = [
        body for title, body in zip(titles, contents)
        if 'how' in title.lower() or 'what' in title.lower()
    ]

    if not picked_bodies:
        return {}

    # Words are lowercased runs of 2+ word characters
    tokenized = [re.findall(r'\w{2,}', body.lower()) for body in picked_bodies]

    n_articles = len(picked_bodies)

    # Document frequency across picked articles
    df = Counter()
    for tokens in tokenized:
        df.update(set(tokens))

    # Smoothed IDF
    idf = {
        word: math.log((1 + n_articles) / (1 + df[word])) + 1
        for word in df
    }

    # Sum L2-normalized TF-IDF vectors across picked articles
    scores_sum = defaultdict(float)

    for tokens in tokenized:
        tf = Counter(tokens)
        vector = {word: count * idf[word] for word, count in tf.items()}

        norm = math.sqrt(sum(value * value for value in vector.values()))
        if norm > 0:
            for word, value in vector.items():
                scores_sum[word] += value / norm

    return dict(scores_sum)
