import math

def replace_and_standardize(data, features, mapping):
    # Raise if any requested feature column is missing
    for feature in features:
        if feature not in data:
            raise ValueError(f"Missing feature column: {feature!r}")

    feature_set = set(features)
    result = {}

    for column, values in data.items():
        # Apply mapping to every column
        replaced = [mapping.get(value, value) for value in values]

        if column not in feature_set:
            result[column] = replaced
            continue

        n = len(replaced)
        if n == 0:
            result[column] = []
            continue

        mean = sum(replaced) / n
        variance = sum((v - mean) ** 2 for v in replaced) / n  # population variance
        std = math.sqrt(variance)

        if std == 0:
            result[column] = [0.0] * n
        else:
            result[column] = [(v - mean) / std for v in replaced]

    return result
