import math
import re
from collections import Counter

def _strip_brackets(text: str) -> str:
    """Lowercase text and replace bracketed spans with spaces."""
    s = text.lower()
    n = len(s)

    # Mark matched [...] intervals using a difference array.
    diff = [0] * (n + 1)
    stack = []

    for i, ch in enumerate(s):
        if ch == '[':
            stack.append(i)
        elif ch == ']':
            if stack:
                start = stack.pop()
                diff[start] += 1
                diff[i + 1] -= 1

    removed = [False] * n
    depth = 0
    for i in range(n):
        depth += diff[i]
        removed[i] = depth > 0

    out = []
    i = 0
    while i < n:
        if removed[i]:
            out.append(' ')
            while i < n and removed[i]:
                i += 1
        else:
            out.append(s[i])
            i += 1

    return ''.join(out)


def bracket_free_tfidf(texts):
    n = len(texts)
    docs = []
    df = {}

    for text in texts:
        words = re.findall(r'\w{2,}', _strip_brackets(text))
        docs.append(words)

        for w in set(words):
            df[w] = df.get(w, 0) + 1

    result = []

    for words in docs:
        if not words:
            result.append({})
            continue

        counts = Counter(words)
        scores = {}

        for w, tf in counts.items():
            idf = math.log((1 + n) / (1 + df[w])) + 1
            scores[w] = tf * idf

        norm = math.sqrt(sum(v * v for v in scores.values()))
        result.append({w: scores[w] / norm for w in sorted(scores)})

    return result
