import csv
import io
import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ORDINAL = r"(?:st|nd|rd|th)?"

_NUM_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_NUM_YEAR_FIRST = re.compile(r"(\d{4})[\s./-]+(\d{1,2})[\s./-]+(\d{1,2})")
_NUM_YEAR_LAST = re.compile(r"(\d{1,2})[\s./-]+(\d{1,2})[\s./-]+(\d{4}|\d{2})")

_MONTH_FIRST = re.compile(
    r"([A-Za-z]+)\.?[\s,./-]+(\d{1,2})" + _ORDINAL + r"[\s,./-]+(\d{4}|\d{2})"
)
_DAY_MONTH_YEAR = re.compile(
    r"(\d{1,2})" + _ORDINAL + r"[\s,./-]+([A-Za-z]+)\.?[\s,./-]+(\d{4}|\d{2})"
)
_YEAR_MONTH_DAY = re.compile(
    r"(\d{4})[\s,./-]+([A-Za-z]+)\.?[\s,./-]+(\d{1,2})" + _ORDINAL
)


def _parse_year(s):
    if len(s) == 4:
        return int(s)
    if len(s) == 2:
        y = int(s)
        return 2000 + y if y < 70 else 1900 + y
    raise ValueError(f"invalid year: {s!r}")


def _month_number(name):
    key = name.lower().rstrip(".")
    if key in _MONTHS:
        return _MONTHS[key]
    raise ValueError(f"unknown month name: {name!r}")


def _make_date(year, month, day, original):
    try:
        return date(year, month, day)
    except ValueError:
        raise ValueError(f"invalid date: {original!r}") from None


def _parse_date(value):
    s = value.strip()
    if not s:
        raise ValueError(f"invalid date: {value!r}")

    # 20200115
    m = _NUM_COMPACT.fullmatch(s)
    if m:
        y, mo, d = map(int, m.groups())
        return _make_date(y, mo, d, value)

    # 2020-01-15, 2020/01/15, 2020.01.15, ...
    m = _NUM_YEAR_FIRST.fullmatch(s)
    if m:
        y, mo, d = map(int, m.groups())
        return _make_date(y, mo, d, value)

    # 01/15/2020, 15/01/2020, 01-15-2020, ...
    m = _NUM_YEAR_LAST.fullmatch(s)
    if m:
        a_str, b_str, y_str = m.groups()
        a, b = int(a_str), int(b_str)
        y = _parse_year(y_str)

        if a > 12 and b <= 12:
            day, month = a, b          # 15/01/2020
        elif b > 12 and a <= 12:
            month, day = a, b          # 01/15/2020
        elif a <= 12 and b <= 12:
            month, day = a, b          # ambiguous: default to month/day/year
        else:
            raise ValueError(f"invalid date: {value!r}")

        return _make_date(y, month, day, value)

    # January 15, 2020 / Jan 15, 2020 / Jan-15-2020
    m = _MONTH_FIRST.fullmatch(s)
    if m:
        mon, day_str, y_str = m.groups()
        month = _month_number(mon)
        day = int(day_str)
        y = _parse_year(y_str)
        return _make_date(y, month, day, value)

    # 15 Jan 2020 / 15-Jan-2020 / 15th Jan 2020
    m = _DAY_MONTH_YEAR.fullmatch(s)
    if m:
        day_str, mon, y_str = m.groups()
        day = int(day_str)
        month = _month_number(mon)
        y = _parse_year(y_str)
        return _make_date(y, month, day, value)

    # 2020 Jan 15 / 2020-Jan-15
    m = _YEAR_MONTH_DAY.fullmatch(s)
    if m:
        y_str, mon, day_str = m.groups()
        y = int(y_str)
        month = _month_number(mon)
        day = int(day_str)
        return _make_date(y, month, day, value)

    raise ValueError(f"invalid date: {value!r}")


def count_dates_by_year(csv_text, date_column):
    """Return {year: count} for dates in the named CSV column."""
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must include a header row") from None

    header = [h.strip().lstrip("\ufeff").strip() for h in header]
    col = date_column.strip().lstrip("\ufeff").strip()

    if col not in header:
        raise ValueError(f"column {date_column!r} not found in header")

    col_idx = header.index(col)
    counts = {}

    for row in reader:
        if not row:
            continue

        value = row[col_idx] if col_idx < len(row) else ""
        d = _parse_date(value)
        counts[d.year] = counts.get(d.year, 0) + 1

    return counts
