import xml.etree.ElementTree as ET

def xml_to_dict(s):
    if not isinstance(s, str) or not s.strip():
        raise ValueError("XML input must not be empty or whitespace-only")

    root = ET.fromstring(s)
    return {root.tag: _element_to_value(root)}


def _element_to_value(elem):
    children = list(elem)

    # Text-only or empty element
    if not children and not elem.attrib:
        return elem.text if elem.text else None

    result = {}

    # Attributes
    for name, value in elem.attrib.items():
        result["@" + name] = value

    # All text content of this element, including text after child elements
    text = _collect_text(elem)
    if text:
        result["#text"] = text

    # Child elements
    for child in children:
        child_value = _element_to_value(child)

        if child.tag in result:
            existing = result[child.tag]
            if isinstance(existing, list):
                existing.append(child_value)
            else:
                result[child.tag] = [existing, child_value]
        else:
            result[child.tag] = child_value

    return result


def _collect_text(elem):
    parts = []
    if elem.text:
        parts.append(elem.text)
    for child in elem:
        if child.tail:
            parts.append(child.tail)
    return "".join(parts)
