from html.parser import HTMLParser


class _TableRecordsParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.found = False
        self.capturing = False
        self.table_depth = 0
        self.target_depth = None
        self.rows = []
        self.current_row = None
        self.current_cell = None

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            self.table_depth += 1
            if not self.capturing:
                attr_map = dict(attrs)
                if attr_map.get("id") == self.table_id:
                    self.found = True
                    self.capturing = True
                    self.target_depth = self.table_depth

        elif tag == "tr":
            if self.capturing and self.table_depth == self.target_depth:
                if self.current_row is not None:
                    self._close_cell()
                self.current_row = []
                self.rows.append(self.current_row)
                self.current_cell = None

        elif tag in ("td", "th"):
            if (
                self.capturing
                and self.table_depth == self.target_depth
                and self.current_row is not None
            ):
                if self.current_cell is not None:
                    self._close_cell()
                self.current_cell = []

    def handle_endtag(self, tag):
        if tag == "table":
            if self.capturing and self.table_depth == self.target_depth:
                self.capturing = False
                self.target_depth = None
            if self.table_depth > 0:
                self.table_depth -= 1

        elif tag == "tr":
            if (
                self.capturing
                and self.table_depth == self.target_depth
                and self.current_row is not None
            ):
                self._close_cell()
                self.current_row = None

        elif tag in ("td", "th"):
            if (
                self.capturing
                and self.table_depth == self.target_depth
                and self.current_cell is not None
            ):
                self._close_cell()

    def handle_data(self, data):
        if self.current_cell is not None:
            self.current_cell.append(data)

    def _close_cell(self):
        if self.current_cell is not None and self.current_row is not None:
            text = "".join(self.current_cell).strip()
            self.current_row.append(text)
        self.current_cell = None


def html_table_records(html, table_id):
    parser = _TableRecordsParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")

    if not parser.rows:
        return []

    headers = parser.rows[0]
    records = []

    for row in parser.rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)

    return records
