import csv
import re
from io import StringIO

_NUMERIC_RE = re.compile(r'^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$')

def _is_numeric(value):
    return bool(_NUMERIC_RE.match(value.strip()))

def _to_number(value):
    value = value.strip()
    try:
        return int(value)
    except ValueError:
        return float(value)

def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    csv_texts = list(csv_texts)
    header = None
    rows = []

    for text in csv_texts:
        if text.startswith('\ufeff'):
            text = text[1:]

        reader = csv.reader(StringIO(text))
        doc_header = next(reader, None)

        if doc_header is None:
            continue

        if header is None:
            header = doc_header

        for row in reader:
            if row:  # skip blank lines
                rows.append(row)

    if header is None:
        raise ValueError("no header row found")

    # Determine which columns are fully numeric across all documents.
    numeric_cols = []
    for i in range(len(header)):
        values = [row[i] if i < len(row) else '' for row in rows]
        numeric_cols.append(bool(values) and all(_is_numeric(v) for v in values))

    result = []
    for row in rows:
        item = {}
        for i, col in enumerate(header):
            value = row[i] if i < len(row) else ''
            if numeric_cols[i]:
                item[col] = _to_number(value)
            else:
                item[col] = value
        result.append(item)

    return result
