import math

def score_grade_correlation(scores, grades):
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    try:
        numeric_scores = [float(s) for s in scores]
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("each score must be a valid number") from exc

    if not all(math.isfinite(x) for x in numeric_scores):
        raise ValueError("each score must be a finite number")

    n = len(numeric_scores)
    if n < 2:
        return None

    # Encode grades by their position in the sorted distinct grade labels
    distinct_grades = sorted(set(grades))
    grade_to_index = {grade: i for i, grade in enumerate(distinct_grades)}
    encoded_grades = [grade_to_index[g] for g in grades]

    mean_x = sum(numeric_scores) / n
    mean_y = sum(encoded_grades) / n

    covariance = sum(
        (x - mean_x) * (y - mean_y)
        for x, y in zip(numeric_scores, encoded_grades)
    )
    variance_x = sum((x - mean_x) ** 2 for x in numeric_scores)
    variance_y = sum((y - mean_y) ** 2 for y in encoded_grades)

    if variance_x == 0 or variance_y == 0:
        return None

    return covariance / math.sqrt(variance_x * variance_y)
