import csv
from io import StringIO

def csv_mean_median(csv_text):
    if not csv_text:
        return (None, None)

    # Read CSV rows, ignoring blank/whitespace-only lines.
    rows = [
        row for row in csv.reader(StringIO(csv_text))
        if row and any(cell.strip() for cell in row)
    ]
    if not rows:
        return (None, None)

    # First non-blank row is the header row; skip it.
    data_rows = rows[1:]

    nums = []
    for row in data_rows:
        if len(row) != 1:
            continue
        try:
            nums.append(float(row[0].strip()))
        except (ValueError, OverflowError):
            continue

    if not nums:
        return (None, None)

    nums.sort()
    n = len(nums)
    mean = sum(nums) / n

    if n % 2 == 1:
        median = nums[n // 2]
    else:
        median = (nums[n // 2 - 1] + nums[n // 2]) / 2.0

    return (float(mean), float(median))
