```python
def box_blur(image, kernel_size):
    if not isinstance(kernel_size, int) or kernel_size <= 0 or kernel_size % 2 != 1:
        raise ValueError("kernel_size must be a positive odd integer")

    height = len(image)
    if height == 0:
        return []

    width = len(image[0])
    if width == 0:
        return [[] for _ in range(height)]

    channels = len(image[0][0])
    half = kernel_size // 2
    area = kernel_size * kernel_size

    def mirror(index, size):
        # Reflect-101 mirroring: border pixel is not repeated.
        # Example: row -1 -> row 1, row size -> row size-2.
        if size == 1:
            return 0
        period = 2 * size - 2
        index %= period
        if index >= size:
            index = period - index
        return index

    result = []
    for r in range(height):
        out_row = []
        for c in range(width):
            sums = [0.0] * channels
            for dr in range(-half, half + 1):
                rr = mirror(r + dr, height)
                img_row = image[rr]
                for dc in range(-half, half + 1):
                    cc = mirror(c + dc, width)
                    pixel = img_row[cc]
                    for ch in range(channels):
                        sums[ch] += pixel[ch]
            out_row.append([s / area for s in sums])
        result.append(out_row)

    return result
