import ast
from html.parser import HTMLParser


class _ScriptExtractor(HTMLParser):
    """Collect the raw text of every <script> element."""

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.script_bodies = []
        self._current = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._current = []

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._current is not None:
            self.script_bodies.append("".join(self._current))
            self._current = None

    def handle_data(self, data):
        if self._current is not None:
            self._current.append(data)

    def close(self):
        super().close()
        # In case of an unterminated <script> tag
        if self._current is not None:
            self.script_bodies.append("".join(self._current))
            self._current = None


def extract_script_dicts(html):
    parser = _ScriptExtractor()
    parser.feed(html)
    parser.close()

    result = []
    for body in parser.script_bodies:
        text = body.strip()
        if not text:
            continue

        try:
            value = ast.literal_eval(text)
        except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
            continue

        if isinstance(value, dict):
            result.append(value)

    return result
```

