import re
import calendar
from datetime import date

_WEEKDAYS = {
    'MON': 0,
    'TUE': 1,
    'WED': 2,
    'THU': 3,
    'FRI': 4,
    'SAT': 5,
    'SUN': 6,
}

def _parse_start_date(start_date):
    if not isinstance(start_date, str) or not re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', start_date):
        raise ValueError(f"Invalid start date: {start_date!r}")
    try:
        return date.fromisoformat(start_date)
    except ValueError:
        raise ValueError(f"Invalid start date: {start_date!r}") from None

def _parse_freq(freq):
    if not isinstance(freq, str):
        raise ValueError(f"Invalid freq: {freq!r}")

    f = freq.strip().upper()

    if f in ('MONTH-END', 'QUARTER-END'):
        return f

    match = re.fullmatch(r'([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)', f)
    if match:
        return int(match.group(1)), match.group(2)

    raise ValueError(f"Invalid freq: {freq!r}")

def _next_month(year, month):
    if month == 12:
        return year + 1, 1
    return year, month + 1

def _nth_weekday(year, month, weekday, n):
    first_weekday = date(year, month, 1).weekday()
    day = 1 + (weekday - first_weekday) % 7 + (n - 1) * 7
    return date(year, month, day)

def forecast_schedule(start_date, freq, sales):
    """
    Pair sales figures with consecutive matching dates starting from start_date.
    """
    start = _parse_start_date(start_date)
    parsed_freq = _parse_freq(freq)
    sales = list(sales)

    # Last day of each month
    if parsed_freq == 'MONTH-END':
        y, m = start.year, start.month
        last_day = calendar.monthrange(y, m)[1]
        current = start if start.day == last_day else date(y, m, last_day)

        result = []
        for value in sales:
            result.append((current.isoformat(), value))
            y, m = _next_month(y, m)
            current = date(y, m, calendar.monthrange(y, m)[1])
        return result

    # Last day of March, June, September, December
    if parsed_freq == 'QUARTER-END':
        if start.month <= 3:
            qm = 3
        elif start.month <= 6:
            qm = 6
        elif start.month <= 9:
            qm = 9
        else:
            qm = 12

        y, m = start.year, qm
        current = date(y, m, calendar.monthrange(y, m)[1])

        result = []
        for value in sales:
            result.append((current.isoformat(), value))
            if current.month == 12:
                y, m = current.year + 1, 3
            else:
                y, m = current.year, current.month + 3
            current = date(y, m, calendar.monthrange(y, m)[1])
        return result

    # Nth weekday of each month, e.g. '2-FRI'
    n, weekday_code = parsed_freq
    weekday = _WEEKDAYS[weekday_code]

    y, m = start.year, start.month
    while True:
        current = _nth_weekday(y, m, weekday, n)
        if current >= start:
            break
        y, m = _next_month(y, m)

    result = []
    for value in sales:
        result.append((current.isoformat(), value))
        y, m = _next_month(y, m)
        current = _nth_weekday(y, m, weekday, n)

    return result
