import csv
import io
from decimal import Decimal, InvalidOperation

def _parse_sales(value):
    try:
        return Decimal(value.strip())
    except InvalidOperation as exc:
        raise ValueError(f"Invalid Sales value: {value!r}") from exc

def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must contain a header row")

    header = [col.strip().lstrip('\ufeff') for col in header]

    try:
        customer_idx = header.index('Customer')
        category_idx = header.index('Category')
        sales_idx = header.index('Sales')
    except ValueError as exc:
        raise ValueError("CSV header must include Customer, Category, and Sales") from exc

    seen = set()
    total = Decimal(0)
    category_counts = {}
    needed_len = max(customer_idx, category_idx, sales_idx) + 1

    for row in reader:
        if not row or all(cell.strip() == '' for cell in row):
            continue

        if len(row) < needed_len:
            raise ValueError("CSV row is missing required columns")

        customer = row[customer_idx].strip()
        if customer in seen:
            continue
        seen.add(customer)

        total += _parse_sales(row[sales_idx])

        category = row[category_idx].strip()
        category_counts[category] = category_counts.get(category, 0) + 1

    if category_counts:
        most_popular = min(
            category_counts.items(),
            key=lambda item: (-item[1], item[0])
        )[0]
    else:
        most_popular = None

    if total == total.to_integral_value():
        total = int(total)
    else:
        total = float(total)

    return {
        'Total Sales': total,
        'Most Popular Category': most_popular
    }
