```python
def _squared_distance(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))


def cluster_point_indices(points, n_clusters):
    """
    Cluster points using k-means and return lists of original point indices.
    Each cluster is sorted ascending, and clusters are ordered by smallest index.
    """
    n = len(points)

    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n < n_clusters:
        raise ValueError("n_clusters cannot exceed the number of points")
    if n == 0:
        return []

    dim = len(points[0])
    if dim == 0:
        raise ValueError("points must have at least one dimension")
    for p in points:
        if len(p) != dim:
            raise ValueError("all points must have the same dimension")

    if n_clusters == 1:
        return [list(range(n))]
    if n_clusters == n:
        return [[i] for i in range(n)]

    # Deterministic initialization: start with the point closest to the mean,
    # then repeatedly add the point farthest from the already chosen centroids.
    mean = [sum(p[k] for p in points) / n for k in range(dim)]
    start = min(range(n), key=lambda i: _squared_distance(points[i], mean))

    centroids = [list(points[start])]
    chosen = {start}

    while len(centroids) < n_clusters:
        best_idx = -1
        best_dist = -1.0
        for i, p in enumerate(points):
            if i in chosen:
                continue
            d = min(_squared_distance(p, c) for c in centroids)
            if d > best_dist:
                best_dist = d
                best_idx = i

        if best_idx == -1:
            break

        centroids.append(list(points[best_idx]))
        chosen.add(best_idx)

    labels = [-1] * n
    max_iterations = 300

    for _ in range(max_iterations):
        # Assignment step: assign each point to the nearest centroid.
        new_labels = [0] * n
        for i, p in enumerate(points):
            best_cluster = 0
            best_dist = _squared_distance(p, centroids[0])
            for c in range(1, n_clusters):
                d = _squared_distance(p, centroids[c])
                if d < best_dist:
                    best_dist = d
                    best_cluster = c
            new_labels[i] = best_cluster

        # Avoid empty clusters by moving a point from a larger cluster.
        counts = [0] * n_clusters
        for label in new_labels:
            counts[label] += 1

        for c in range(n_clusters):
            if counts[c] == 0:
                candidates = [
                    i for i in range(n)
                    if counts[new_labels[i]] > 1
                ]
                if not candidates:
                    candidates = [
                        i for i in range(n)
                        if new_labels[i] != c
                    ]
                if not candidates:
                    continue

                far = max(
                    candidates,
                    key=lambda i: _squared_distance(
                        points[i], centroids[new_labels[i]]
                    )
                )
                old = new_labels[far]
                new_labels[far] = c
                counts[old] -= 1
                counts[c] += 1

        # Update step: recompute centroids as cluster means.
        new_centroids = []
        for c in range(n_clusters):
            members = [points[i] for i in range(n) if new_labels[i] == c]
            if members:
                new_centroids.append([
                    sum(pt[k] for pt in members) / len(members)
                    for k in range(dim)
                ])
            else:
                new_centroids.append(list(centroids[c]))

        if new_labels == labels:
            labels = new_labels
            centroids = new_centroids
            break

        labels = new_labels
        centroids = new_centroids

    clusters = [[] for _ in range(n_clusters)]
    for i, label in enumerate(labels):
        clusters[label].append(i)

    # Defensive cleanup, then order clusters by their smallest index.
    clusters = [c for c in clusters if c]
    clusters.sort(key=lambda c: c[0])
    return clusters
