def csv_cube_roots(csv_text, columns):
    columns = list(columns)
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        header = []

    data = {name: [] for name in header}

    for row in reader:
        for name, raw in zip(header, row):
            data[name].append(float(raw))   # raises ValueError if non-numeric

    for col in columns:
        if col not in data:
            raise KeyError(col)

    cube_roots = {
        col: [math.copysign(abs(value) ** (1.0 / 3.0), value)
              for value in data[col]]
        for col in columns
    }

    return data, cube_roots
