def complete_row_histogram(data, bins):
    bins = int(bins)

    if not data:
        return {}, None

    cols = list(data.keys())
    n = len(data[cols[0]])

    # Keep only rows with no None in any column
    keep = [
        i for i in range(n)
        if all(data[col][i] is not None for col in cols)
    ]

    # Cast kept values to float to match the example output
    cleaned = {
        col: [float(data[col][i]) for i in keep]
        for col in cols
    }

    pooled = [data[col][i] for col in cols for i in keep]

    if not pooled:
        counts = None
    else:
        lo = min(pooled)
        hi = max(pooled)

        if lo == hi:
            counts = None
        else:
            counts = [0] * bins

            for value in pooled:
                if value == hi:
                    idx = bins - 1
                elif isinstance(value, int) and isinstance(lo, int) and isinstance(hi, int):
                    # Exact integer binning
                    idx = (value - lo) * bins // (hi - lo)
                else:
                    idx = int((value - lo) * bins / (hi - lo) + 1e-12)

                if idx < 0:
                    idx = 0
                elif idx >= bins:
                    idx = bins - 1

                counts[idx] += 1

    return cleaned, counts
