import csv
import io
import math

def correlation_matrix_from_csv(csv_text):
    reader = csv.DictReader(io.StringIO(csv_text))
    header = reader.fieldnames
    if header is None:
        return {}

    columns = {col: [] for col in header}
    for row in reader:
        for col in header:
            try:
                columns[col].append(float(row[col]))
            except (TypeError, ValueError):
                columns[col].append(float("nan"))

    n = len(next(iter(columns.values()))) if columns else 0
    centered = {}
    for col, values in columns.items():
        mean = sum(values) / n if n else float("nan")
        centered[col] = [v - mean for v in values]

    def pearson(xs, ys):
        if not xs or len(xs) != len(ys):
            return float("nan")
        num = sum(x * y for x, y in zip(xs, ys))
        den_x = sum(x * x for x in xs)
        den_y = sum(y * y for y in ys)
        den = math.sqrt(den_x * den_y)
        if den == 0.0:
            return float("nan")
        r = num / den
        if math.isnan(r):
            return r
        return max(-1.0, min(1.0, r))

    return {
        a: {b: pearson(centered[a], centered[b]) for b in header}
        for a in header
    }
