def document_term_matrix(texts, stop_words):
    stop = {s.lower() for s in stop_words}
    tokenized = []
    vocab = set()

    for text in texts:
        words = []
        current = []

        for ch in text.lower():
            # Letters and digits are word characters; everything else,
            # including underscores, separates words.
            if ch.isalpha() or ch.isdigit():
                current.append(ch)
            else:
                if current:
                    word = ''.join(current)
                    if word not in stop:
                        words.append(word)
                        vocab.add(word)
                    current = []

        if current:
            word = ''.join(current)
            if word not in stop:
                words.append(word)
                vocab.add(word)

        tokenized.append(words)

    terms = sorted(vocab)
    term_index = {term: i for i, term in enumerate(terms)}

    counts = []
    for words in tokenized:
        row = [0] * len(terms)
        for word in words:
            row[term_index[word]] += 1
        counts.append(row)

    return terms, counts
```

