def normalize_columns(data):
    if not data:
        raise ValueError("data dict must not be empty")

    normalized = {}

    for column, values in data.items():
        # Validate that every value is numeric (int or float, not bool)
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Column {column!r} contains a non-numeric value: {value!r}"
                )

        if not values:
            raise ValueError(f"Column {column!r} is empty")

        low = min(values)
        high = max(values)

        if high == low:
            normalized[column] = [0.0 for _ in values]
        else:
            span = high - low
            normalized[column] = [(value - low) / span for value in values]

    return normalized
