from collections import Counter

def column_summary_stats(table, mapping, features):
    def replace(value):
        # Use dict lookup when possible; fall back to equality for unhashable values.
        try:
            return mapping.get(value, value)
        except TypeError:
            for key, replacement in mapping.items():
                if value == key:
                    return replacement
            return value

    result = {}

    for name in features:
        if name not in table:
            raise ValueError(f"Requested feature {name!r} is not in the table")

        values = [replace(v) for v in table[name]]
        n = len(values)

        if n == 0:
            raise ValueError(f"Column {name!r} is empty; cannot compute summary statistics")

        mean = sum(values) / n

        ordered = sorted(values)
        if n % 2 == 1:
            median = float(ordered[n // 2])
        else:
            median = float((ordered[n // 2 - 1] + ordered[n // 2]) / 2)

        counts = Counter(values)
        max_count = max(counts.values())
        mode = min(value for value, count in counts.items() if count == max_count)

        variance = sum((value - mean) ** 2 for value in values) / n

        result[name] = {
            "mean": mean,
            "median": median,
            "mode": mode,
            "variance": variance,
        }

    return result
