from html.parser import HTMLParser


class _LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)  # decode entities in text
        self.links = []
        self._open = []  # stack of indices for currently open <a> tags

    @staticmethod
    def _get_href(attrs):
        for name, value in attrs:
            if name == "href":
                return value
        return None

    def handle_starttag(self, tag, attrs):
        if tag == "a":
            idx = len(self.links)
            self.links.append([[], self._get_href(attrs)])
            self._open.append(idx)

    def handle_startendtag(self, tag, attrs):
        # Handles self-closing <a ... /> as an empty link
        if tag == "a":
            self.links.append(("", self._get_href(attrs)))

    def handle_endtag(self, tag):
        if tag == "a" and self._open:
            idx = self._open.pop()
            parts, href = self.links[idx]
            self.links[idx] = ("".join(parts), href)

    def handle_data(self, data):
        # Append text to all currently open <a> tags
        for idx in self._open:
            self.links[idx][0].append(data)

    def close(self):
        super().close()
        # Flush any unclosed <a> tags
        while self._open:
            idx = self._open.pop()
            parts, href = self.links[idx]
            self.links[idx] = ("".join(parts), href)


def extract_links(html):
    """Return a list of (text, href) for every <a> tag in html."""
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return parser.links
