from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.table_depth = 0
        self.done = False

        self.headers = []
        self.rows = []

        self._row_cells = None      # td cells for the current <tr>
        self._cell_kind = None      # 'th' or 'td'
        self._cell_text = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if tag == "table":
            self.table_depth += 1
            if self.table_depth == 1:
                self.found_table = True
            return

        if not self.found_table or self.table_depth != 1:
            return

        if tag == "tr":
            self._start_row()
        elif tag in ("td", "th"):
            self._start_cell(tag)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if self.done:
            return

        if tag == "table":
            if self.table_depth > 0:
                self.table_depth -= 1
                if self.table_depth == 0:
                    self._end_row()
                    self.done = True
            return

        if not self.found_table or self.table_depth != 1:
            return

        if tag == "tr":
            self._end_row()
        elif tag in ("td", "th"):
            self._end_cell()

    def handle_data(self, data):
        if self.done or not self.found_table:
            return
        if self._cell_kind is not None:
            self._cell_text.append(data)

    def _start_row(self):
        if self._row_cells is not None:
            self._end_row()
        self._row_cells = []

    def _end_row(self):
        self._end_cell()
        if self._row_cells is not None:
            if self._row_cells:
                self.rows.append(self._row_cells)
            self._row_cells = None

    def _start_cell(self, kind):
        self._end_cell()
        self._cell_kind = kind
        self._cell_text = []

    def _end_cell(self):
        if self._cell_kind is None:
            return

        text = "".join(self._cell_text).strip()

        if self._cell_kind == "th":
            self.headers.append(text)
        elif self._cell_kind == "td" and self._row_cells is not None:
            self._row_cells.append(text)

        self._cell_kind = None
        self._cell_text = []

    def finalize(self):
        if self.found_table and not self.done:
            self._end_row()
            self.done = True


def extract_first_table(html):
    """Extract the first <table> in an HTML string.

    Returns (headers, rows), where headers is a list of stripped <th> texts
    and rows is a list of lists of stripped <td> texts for each <tr> that
    contains at least one <td>.
    """
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()

    if not parser.found_table:
        raise ValueError("no <table> found")
    if not parser.rows:
        raise ValueError("first <table> has no data rows")

    return parser.headers, parser.rows
