import math

def row_zscores_and_correlation(data):
    # Row-wise z-scores using population standard deviation
    z = []
    for row in data:
        n = len(row)
        if n == 0:
            z.append([])
            continue

        mean = sum(row) / n
        sd = math.sqrt(sum((x - mean) ** 2 for x in row) / n)

        if sd == 0:
            z.append([0.0] * n)
        else:
            z.append([(x - mean) / sd for x in row])

    if not z:
        return z, []

    rows = len(z)
    columns = list(zip(*z))   # columns of the z-score matrix
    cols = len(columns)

    # Column means and population standard deviations across rows
    col_means = [sum(col) / rows for col in columns]
    col_sds = [
        math.sqrt(sum((x - mean) ** 2 for x in col) / rows)
        for col, mean in zip(columns, col_means)
    ]

    # Pearson correlation matrix between columns
    corr = [[0.0] * cols for _ in range(cols)]
    for i in range(cols):
        for j in range(cols):
            if i == j:
                corr[i][j] = 1.0
            else:
                denom = col_sds[i] * col_sds[j]
                if denom == 0:
                    corr[i][j] = float("nan")  # undefined if a column is constant
                else:
                    cov = sum(
                        (x - col_means[i]) * (y - col_means[j])
                        for x, y in zip(columns[i], columns[j])
                    ) / rows
                    corr[i][j] = cov / denom

    return z, corr
