from datetime import datetime, timedelta, timezone

def timestamp_dates_and_histogram(timestamps):
    if len(timestamps) == 0:
        raise ValueError("timestamps list is empty")

    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    dates = [
        (epoch + timedelta(seconds=ts)).strftime("%Y-%m-%d %H:%M:%S")
        for ts in timestamps
    ]

    lo = min(timestamps)
    hi = max(timestamps)
    counts = [0] * 10

    if lo == hi:
        # All values equal the maximum, so they fall in the last bin.
        counts[9] = len(timestamps)
    else:
        width = (hi - lo) / 10.0
        for ts in timestamps:
            if ts == hi:
                idx = 9  # last bin includes the maximum
            else:
                idx = int((ts - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx > 9:
                    idx = 9
            counts[idx] += 1

    return dates, counts
