def standardize_filtered(data, age, weight):
    for key in ('Age', 'Weight'):
        if key not in data:
            raise KeyError(key)

    ages = data['Age']
    weights = data['Weight']

    kept = [
        i for i in range(len(ages))
        if ages[i] < age and weights[i] > weight
    ]

    if not kept:
        return {col: [] for col in data}

    result = {}

    for col, values in data.items():
        vals = [values[i] for i in kept]

        # Constant column (including a single kept row) -> all zeros
        if all(v == vals[0] for v in vals):
            result[col] = [0.0] * len(vals)
            continue

        mean = sum(vals) / len(vals)
        variance = sum((v - mean) ** 2 for v in vals) / len(vals)
        std = variance ** 0.5

        if std == 0.0:
            result[col] = [0.0] * len(vals)
        else:
            result[col] = [(v - mean) / std for v in vals]

    return result
