import re
import fnmatch

def _natural_key(filename):
    # Split into text and number chunks so numbers compare numerically.
    return [
        int(part) if part.isdecimal() else part
        for part in re.split(r'(\d+)', filename)
    ]

def extract_matches_from_files(files, name_pattern, value_pattern):
