import csv
import io
import re
from typing import Any, Dict, List

_INT_RE = re.compile(r"[+-]?\d+")
_FLOAT_RE = re.compile(r"[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?")

def _is_number(value: str) -> bool:
    value = value.strip()
    return bool(_INT_RE.fullmatch(value) or _FLOAT_RE.fullmatch(value))

def _to_number(value: str):
    value = value.strip()
    if _INT_RE.fullmatch(value):
        return int(value)
    return float(value)

def sort_csv_rows(csv_text: str, sort_by_column: str) -> List[Dict[str, Any]]:
    rows = list(csv.reader(io.StringIO(csv_text)))

    if not rows:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    header = rows[0]

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    data = []
    for row in rows[1:]:
        if not row:
            continue
        data.append({
            col: row[i] if i < len(row) else ""
            for i, col in enumerate(header)
        })

    # Convert columns whose values are all numbers.
    for col in header:
        if all(_is_number(row[col]) for row in data):
            for row in data:
                row[col] = _to_number(row[col])

    data.sort(key=lambda row: row[sort_by_column])
    return data
