from bisect import bisect_right

def histogram_bins(values, bins):
    values = list(values)

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")
        if not values:
            return [], []

        lo = min(values)
        hi = max(values)
        width = (hi - lo) / bins

        edges = [float(lo + i * width) for i in range(bins)]
        edges.append(float(hi))
    else:
        edges = [float(e) for e in bins]
        if len(edges) < 2:
            return [], edges

    n = len(edges) - 1
    counts = [0] * n
    first, last = edges[0], edges[-1]

    for v in values:
        if v < first or v > last:
            continue

        idx = bisect_right(edges, v) - 1

        # Last bin includes its right edge.
        if idx >= n:
            idx = n - 1
        elif idx < 0:
            idx = 0

        counts[idx] += 1

    return counts, edges
