def attribute_histogram(records, key, num_bins=30):
    if num_bins <= 0:
        raise ValueError("num_bins must be positive")

    values = [record[key] for record in records]
    if not values:
        raise ValueError("records must not be empty")

    lo, hi = min(values), max(values)

    # All values are equal: zero-width bins; put them all in the last bin.
    if lo == hi:
        counts = [0] * num_bins
        counts[-1] = len(values)
        edges = [float(lo)] * (num_bins + 1)
        return counts, edges

    width = (hi - lo) / num_bins

    edges = [float(lo + i * width) for i in range(num_bins)]
    edges.append(float(hi))

    counts = [0] * num_bins
    for v in values:
        if v == hi:
            idx = num_bins - 1
        else:
            idx = int((v - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= num_bins:
                idx = num_bins - 1
        counts[idx] += 1

    return counts, edges
