import re
from html.parser import HTMLParser
from urllib.parse import urljoin

_ABSOLUTE_URL_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


class _LinkExtractor(HTMLParser):
    def __init__(self, base_url):
        super().__init__(convert_charrefs=True)
        self.base_url = base_url
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "a":
            for name, value in attrs:
                if name.lower() == "href":
                    href = (value or "").strip()
                    if _ABSOLUTE_URL_RE.match(href):
                        self.links.append(href)
                    else:
                        self.links.append(urljoin(self.base_url, href))
                    break

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def extract_page_links(html, base_url):
    parser = _LinkExtractor(base_url)
    parser.feed(html)
    parser.close()
    return parser.links
```

This uses only the standard library. It walks the HTML in document order, so duplicates are preserved, and it skips `<a>` tags without an `href` attribute. Relative URLs are resolved with `urljoin` against `base_url`; absolute URLs are kept as-is.

