from html.parser import HTMLParser

class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.row_stack = []   # each entry: {'cells': [], 'depth': table_depth}
        self.cell_stack = []  # each entry: (row, cell_chunks)
        self.table_depth = 0

    def _close_cells_for_row(self, row):
        while self.cell_stack and self.cell_stack[-1][0] is row:
            self.cell_stack.pop()

    def _close_row(self):
        if not self.row_stack:
            return
        row = self.row_stack.pop()
        self._close_cells_for_row(row)

    def _close_rows_at_depth(self, depth):
        while self.row_stack and self.row_stack[-1]['depth'] >= depth:
            self._close_row()
        while self.cell_stack and self.cell_stack[-1][0]['depth'] >= depth:
            self.cell_stack.pop()

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            self.table_depth += 1
        elif tag == 'tr':
            # A new <tr> in the same table closes any open row at this depth.
            while self.row_stack and self.row_stack[-1]['depth'] >= self.table_depth:
                self._close_row()
            row = {'cells': [], 'depth': self.table_depth}
            self.rows.append(row)
            self.row_stack.append(row)
        elif tag in ('td', 'th'):
            if self.row_stack and self.row_stack[-1]['depth'] == self.table_depth:
                row = self.row_stack[-1]
                self._close_cells_for_row(row)  # implied end of previous cell
                if tag == 'td':
                    cell = []
                    row['cells'].append(cell)
                    self.cell_stack.append((row, cell))

    def handle_endtag(self, tag):
        if tag == 'table':
            if self.table_depth > 0:
                self._close_rows_at_depth(self.table_depth)
                self.table_depth -= 1
        elif tag == 'tr':
            if self.row_stack and self.row_stack[-1]['depth'] == self.table_depth:
                self._close_row()
        elif tag == 'td':
            if self.cell_stack:
                self.cell_stack.pop()

    def handle_data(self, data):
        # Append text to every open <td>; nested table text is part of ancestor <td> text.
        for _, cell in self.cell_stack:
            cell.append(data)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()

    return [
        [''.join(cell).strip() for cell in row['cells']]
        for row in parser.rows
    ]
```

