import json
from html import unescape
from html.parser import HTMLParser

class _TitleParser(HTMLParser):
    # Treat <title> as raw text (like script/style) so its contents are captured literally.
    CDATA_CONTENT_ELEMENTS = ("script", "style", "title")

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self._found_title = False
        self._in_title = False
        self._raw_parts = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "title" and not self._found_title:
            self._found_title = True
            self._in_title = True
            self._raw_parts = []

    def handle_endtag(self, tag):
        if tag.lower() == "title" and self._in_title:
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self._raw_parts.append(data)

    def get_title(self):
        if not self._found_title:
            return None
        return unescape("".join(self._raw_parts))


def extract_title_json(html):
    parser = _TitleParser()
    parser.feed(html)
    parser.close()
    return json.dumps({"title": parser.get_title()})
